function showHangar(){state='hangar';run=null;$('hud').classList.add('hidden');$('touch').classList.add('hidden');renderHangar();}
function renderHangar(){cfg=configure(selection,mission);setOverlay(`<section class="hangar"><div class="hero"><div><div class="eyebrow">AN ENGINEER'S ODYSSEY · 2.5D FIELD SIMULATOR</div><h1>BUILD. EXPLORE.<br><em>UNDERSTAND.</em></h1><p>Your next discovery starts with a decision. Build a spacecraft, brave the field, and bring the science home.</p></div><div class="record">MISSION ARCHIVE<strong>${Object.values(best).filter(x=>x>0).length} / 3 destinations</strong>Learn through each attempt.<br>Return with a better design.</div></div><div class="section-title">01 / CHOOSE YOUR FRONTIER <span>TRAINING CAMPAIGN</span></div><div class="destinations">${missions.map(m=>`<button class="destination ${m.id===mission.id?'active':''}" data-mission="${m.id}" aria-pressed="${m.id===mission.id}"><div class="planet ${m.id}"></div><small>${m.tag}</small><h2>${m.name}</h2><p>${m.au} AU FROM THE SUN · ${m.gravity} m/s²</p></button>`).join('')}</div><div class="workshop"><div><div class="section-title">02 / ENGINEER YOUR LOADOUT <span>EVERY CHOICE HAS A COST</span></div><div class="module-grid">${Object.entries(modules).map(([key,items])=>`<div class="module-group"><label>${key==='comms'?'Communications':key}</label>${items.map(m=>`<button class="module ${selection[key]===m.id?'active':''}" data-group="${key}" data-module="${m.id}" aria-pressed="${selection[key]===m.id}"><span class="radio"></span><span><strong>${m.name}</strong><small>${m.detail}</small></span></button>`).join('')}</div>`).join('')}</div></div><aside class="preflight"><div class="eyebrow">PREFLIGHT / DESIGN REVIEW</div><h3>${mission.name}</h3><div class="stat-line">Budget <b class="${cfg.cost>165?'bad':''}">${cfg.cost} / 165 cr</b></div><div class="stat-line">Launch mass <b class="${cfg.mass>cfg.launcher.capacity?'bad':''}">${cfg.mass} / ${cfg.launcher.capacity} kg</b></div><div class="stat-line">Sunlit power <b>${Math.round(cfg.generation)} W</b></div><div class="stat-line">Peak demand <b>${cfg.demand} W</b></div><div class="stat-line">Battery capacity <b>30 Wh</b></div><p class="science-note">${cfg.errors.length?`<span class="bad">${cfg.errors.join(' ')}</span>`:cfg.generation<cfg.demand?'Power deficit at peak load. Battery time is limited: scan deliberately and return before depletion.':'Design fits the launch limits. Watch the battery when sunlight disappears.'}</p><button id="launch" class="primary" ${cfg.errors.length?'disabled':''}>DEPLOY SIMULATION <span>↗</span></button></aside></div><p class="bottom-note">WASD / arrows: move · Space: dash · E: hold to scan · Q: defensive pulse · P: pause<br>Original pixel-art prototype. Fictional hardware and accelerated scenarios; not a mission-certified simulator. Sources and model limits are in the Field Codex.</p></section>`);
 document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{mission=missions.find(m=>m.id===b.dataset.mission);renderHangar();beep(350);});document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>{selection[b.dataset.group]=b.dataset.module;renderHangar();beep(500);});$('launch').onclick=start;
}
function start(){cfg=configure(selection,mission);if(cfg.errors.length)return;run={time:0,hp:100,wh:30,heat:0,stored:0,returned:0,scans:0,kills:0,damage:0,dash:0,pulse:0,invuln:0,upgrade:false,field:'sunlight',light:1,gen:cfg.generation,contact:true,scanTime:0,finished:false,log:[],p:{x:0,y:210,dx:0,dy:-1},nodes:[{x:-225,y:-70,done:false},{x:205,y:-180,done:false},{x:265,y:155,done:false}],enemies:[],shots:[],sparks:[],rings:[],spawn:2,up:{shield:1,cooling:1,rate:1}};state='play';setOverlay('');$('hud').classList.remove('hidden');$('touch').classList.remove('hidden');$('location').textContent=mission.name;$('task').textContent=mission.objective;announce('Find the three glowing sites. Hold E nearby to scan.');beep(650,.18);}
