function upgrade(){state='upgrade';setOverlay(`<section class="modal"><div class="eyebrow">FIELD REVIEW / TWO SITES MAPPED</div><h1>Adapt your strategy.</h1><p>Choose one simulated subsystem improvement. Real hardware cannot be magically replaced during a mission; this is a training reward.</p><div class="cards"><button class="upgrade" data-up="shield"><strong>Fault protection · 30% less damage</strong><p>Preserve integrity while bringing your measurements home.</p></button><button class="upgrade" data-up="cooling"><strong>Thermal management · 60% faster cooling</strong><p>Recover from scan and pulse heat more quickly.</p></button><button class="upgrade" data-up="rate"><strong>Ground network · 50% faster downlink</strong><p>Clear the data buffer faster during contact windows.</p></button></div></section>`);document.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>{const k=b.dataset.up;run.up[k]=k==='shield'?.7:k==='cooling'?1.6:1.5;run.log.push(`Selected ${k} improvement after comparing constraints.`);resume();announce('Upgrade applied. Finish the survey and reach the uplink.');});}
