 if(Math.hypot(p.x,p.y-285)<75){if(r.stored>0){if(r.contact){const transfer=Math.min(r.stored,cfg.comms.rate*r.up.rate*dt);r.stored-=transfer;r.returned+=transfer;demand+=cfg.comms.watts;prompt='UPLINK ACTIVE · stay within the beacon';}else prompt=`NO CONTACT · next window in ${Math.ceil(18-r.time%18)}s`;}else prompt=r.scans<3?'UPLINK READY · scan more sites':'All measurements transmitted';}
